1	package com.example.starter.service;
2	
3	import java.math.BigDecimal;
4	import java.sql.Timestamp;
5	import java.util.List;
6	import java.util.Optional;
7	
8	import org.springframework.dao.DuplicateKeyException;
9	import org.springframework.jdbc.core.JdbcTemplate;
10	import org.springframework.stereotype.Service;
11	import org.springframework.transaction.PlatformTransactionManager;
12	import org.springframework.transaction.support.TransactionTemplate;
13	
14	import com.example.starter.support.AppClock;
15	import com.example.starter.support.Fingerprints;
16	import com.example.starter.web.ConflictException;
17	import com.example.starter.web.dto.RestoreConfirmRequest;
18	import com.example.starter.web.dto.RestoreConfirmResponse;
19	
20	/**
21	 * 复电确认服务：调度与现场双确认方生效，复电确认与负荷恢复记录同事务完成；
22	 * 复电后释放班组并自动提升挂单；封存后迟到回报只记迟到事件。
23	 */
24	@Service
25	public class RestoreService {
26	
27	    private final JdbcTemplate jdbc;
28	    private final AppClock clock;
29	    private final WorkOrderStore store;
30	    private final TransactionTemplate tx;
31	
32	    public RestoreService(JdbcTemplate jdbc, AppClock clock, WorkOrderStore store,
33	            PlatformTransactionManager txManager) {
34	        this.jdbc = jdbc;
35	        this.clock = clock;
36	        this.store = store;
37	        this.tx = new TransactionTemplate(txManager);
38	    }
39	
40	    /**
41	     * 复电确认：同 requestId 同参返回首次结果，同键异参抛 409；单人不生效，双角色齐全才复电。
42	     */
43	    public RestoreConfirmResponse confirm(RestoreConfirmRequest req) {
44	        if (!"DISPATCHER".equals(req.role()) && !"FIELD".equals(req.role())) {
45	            throw new IllegalArgumentException("非法确认角色: " + req.role());
46	        }
47	        if ("FIELD".equals(req.role()) && (req.loadKw() == null || req.loadKw().signum() <= 0)) {
48	            throw new IllegalArgumentException("现场确认必须携带正的恢复负荷 loadKw");
49	        }
50	        String fingerprint = Fingerprints.of(req.requestId(), req.workOrderId(), req.role(),
51	                req.confirmer(), req.loadKw());
52	        try {
53	            return tx.execute(status -> doConfirm(req, fingerprint));
54	        } catch (DuplicateKeyException e) {
55	            return tx.execute(status -> findReplay(req.requestId(), fingerprint)
56	                    .orElseThrow(() -> e));
57	        }
58	    }
59	
60	    private RestoreConfirmResponse doConfirm(RestoreConfirmRequest req, String fingerprint) {
61	        Optional<RestoreConfirmResponse> replay = findReplay(req.requestId(), fingerprint);
62	        if (replay.isPresent()) {
63	            return replay.get();
64	        }
65	        WorkOrderRow order = store.requireById(req.workOrderId());
66	        if ("SEALED".equals(order.status())) {
67	            // 封存为终态：迟到回报只记迟到事件，不改变工单状态
68	            insertConfirmation(req, fingerprint);
69	            jdbc.update("INSERT INTO late_report_event (work_order_id, event_type, detail, created_at)"
70	                    + " VALUES (?,?,?,?)",
71	                    req.workOrderId(), "LATE_RESTORE_CONFIRM",
72	                    "封存后迟到复电确认, 角色=" + req.role() + ", 确认人=" + req.confirmer(),
73	                    Timestamp.valueOf(clock.now()));
74	            return new RestoreConfirmResponse(req.workOrderId(), false, true, "SEALED", false);
75	        }
76	        if (!"EXECUTING".equals(order.status())) {
77	            throw new ConflictException("工单状态不可复电确认: " + order.status());
78	        }
79	        List<String> priorConfirmers = jdbc.query(
80	                "SELECT confirmer FROM restore_confirmation WHERE work_order_id = ?",
81	                (rs, rowNum) -> rs.getString(1), req.workOrderId());
82	        if (priorConfirmers.contains(req.confirmer())) {
83	            throw new ConflictException("同一确认人不可重复确认（单人不生效）: " + req.confirmer());
84	        }
85	        List<String> priorRoles = jdbc.query(
86	                "SELECT DISTINCT confirmer_role FROM restore_confirmation WHERE work_order_id = ?",
87	                (rs, rowNum) -> rs.getString(1), req.workOrderId());
88	        if (priorRoles.contains(req.role())) {
89	            throw new ConflictException("角色已确认过: " + req.role());
90	        }
91	        insertConfirmation(req, fingerprint);
92	        priorRoles.add(req.role());
93	        if (!(priorRoles.contains("DISPATCHER") && priorRoles.contains("FIELD"))) {
94	            return new RestoreConfirmResponse(req.workOrderId(), false, false, "EXECUTING", false);
95	        }
96	        // 双确认齐全：复电与负荷恢复记录在同一事务内完成
97	        BigDecimal loadKw = jdbc.queryForObject(
98	                "SELECT load_kw FROM restore_confirmation WHERE work_order_id = ? AND confirmer_role = 'FIELD'",
99	                BigDecimal.class, req.workOrderId());
100	        jdbc.update("UPDATE work_order SET status = 'RESTORED', restored_at = ?, executing_team_id = NULL"
101	                + " WHERE id = ?", Timestamp.valueOf(clock.now()), req.workOrderId());
