                new ArrivalRequest("gd-12-a2", 1L, t4, D0.plusSeconds(2200)));
        assertEquals("ALL_ARRIVED", all.outcome());
        assertEquals(1, count("supply_evidence", "dispatch_id = ?", re.newDispatchId()));
    }

